EXPECTED_SHA256 = "d3b8448463c51530fb20b3a06326b20766ca1a6c240ba5824502e251fcf1e532"


def main():
    data = base64.b64decode("".join(IMAGE_B64))
    assert hashlib.sha256(data).hexdigest() == EXPECTED_SHA256, "image bytes changed"
    assert len(data) <= 1048576, "image over 1 MiB"
    try:
        os.makedirs("/output", exist_ok=True)
        path = "/output/entry.png"
        with open(path, "wb") as f:
            f.write(data)
    except OSError:
        os.makedirs("output", exist_ok=True)
        path = os.path.join("output", "entry.png")
        with open(path, "wb") as f:
            f.write(data)
    print("wrote %s %d bytes sha256=%s" % (path, len(data), EXPECTED_SHA256))
    return 0


if __name__ == "__main__":
    sys.exit(main())
